    receiveWathbaMemberWebhook: {
        parameters: {
            query?: never;
            header: {
                /** @description Source event identifier used for durable replay protection */
                "X-Wathba-Event-Id": string;
                /** @description Stable delivery identifier reused across retries; receivers should deduplicate repeated delivery attempts by this value */
                "X-Wathba-Delivery-Id": string;
                /** @description Unix timestamp in seconds included in the signature input */
                "X-Wathba-Timestamp": string;
                /** @description HMAC-SHA-256 signature over timestamp, a dot, and the exact raw body */
                "X-Wathba-Signature": string;
                /** @description Exact numeric signing-secret version; receivers must never fall back */
                "X-Wathba-Signature-Version": string;
            };
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                /**
                 * @example {
                 *       "alertKey": "otp_allowance_near_exhausted",
                 *       "eventId": "evt_otp_allowance_123",
                 *       "eventType": "OtpAllowanceNearExhausted",
                 *       "payload": {
                 *         "environmentId": "env_123",
                 *         "memberId": "mem_123",
                 *         "projectId": "prj_123",
                 *         "remaining": 5
                 *       },
                 *       "payloadVersion": 1
                 *     }
                 */
                "application/json": components["schemas"]["MemberWebhookEvent"];
            };
        };
        responses: {
            /** @description Event authenticated and durably claimed */
            204: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
        };
    };
